  start: { q: 'Is it a deprivation of liberty (considering type, duration, effects, manner) rather than a restriction on movement?', o: [['Yes — e.g. locked up, continuous supervision and not free to leave', 'exc'], ['No — a limited restriction, e.g. short kettling to prevent violence', 'nodep']] },
  nodep: { end: true, tone: 'mid', v: 'Article 5 probably not engaged', x: 'Context and purpose matter. Consider Arts 8, 10, 11 instead.', cases: ['austinuk', 'guzzardi'] },
  exc: { q: 'Does it fall within an Art 5(1) exception?', o: [['After conviction', 'law'], ['Arrest on reasonable suspicion of an offence', 'law'], ['Unsound mind / infectious disease', 'law'], ['Immigration or deportation', 'law'], ['None — e.g. indefinite detention without charge of suspects not being deported', 'bre']] },
  bre: { end: true, tone: 'bad', v: 'Breach of Article 5(1)', x: '', cases: ['belmarsh'] },
  law: { q: 'Was it in accordance with a procedure prescribed by law, with safeguards?', o: [['Yes', 'proc'], ['No — informal detention with no legal framework', 'bre2']] },
